from __future__ import annotations

import re
from datetime import datetime, timezone


_DATE_RE = re.compile(
    r"^(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), [0-9]{2} "
    r"(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) "
    r"[0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2} GMT$"
)


def parse_retry_after(value: str, *, now: datetime, max_delay: int) -> int | None:
    """Return a bounded Retry-After delay, or None for an invalid value."""
    text = value.strip()
    if not text:
        return None

    if re.fullmatch(r"[0-9]+", text):
        try:
            delay = int(text)
        except ValueError:
            return None
    else:
        if not _DATE_RE.fullmatch(text):
            return None
        try:
            target = datetime.strptime(
                text, "%a, %d %b %Y %H:%M:%S GMT"
            ).replace(tzinfo=timezone.utc)
        except ValueError:
            return None
        try:
            delay = max(0, int((target - now).total_seconds()))
        except (TypeError, ValueError):
            return None

    return min(delay, max(0, max_delay))
